//! Access to the frontend assets embedded in the binary.
//!
//! The asset table is generated by `build.rs` and included as
//! `$OUT_DIR/embedded_assets.rs`. Each entry maps a path relative to the
//! frontend output directory to its bytes, so the service can answer a
//! request for a static file without reading the filesystem.
//!
//! When no frontend has been built, the table is empty and
//! [`placeholder`] supplies a self-contained page that explains the state of
//! the build. The service therefore always answers something useful.
//!
//! 对内嵌在二进制中的前端资源的访问。
//!
//! 资源表由 `build.rs` 生成并作为 `$OUT_DIR/embedded_assets.rs` 引入。每个条目
//! 把相对前端输出目录的路径映射到其字节，因此服务无需读取文件系统即可回应静态
//! 文件请求。
//!
//! 尚未构建前端时，该表为空，[`placeholder`] 提供一个自足页面说明构建状态。
//! 因此服务总能给出有用的回应。

include!(concat!(env!("OUT_DIR"), "/embedded_assets.rs"));

/// A built-in page served when no frontend build is embedded.
///
/// 未嵌入前端构建时提供的内置页面。
const PLACEHOLDER: &str = r#"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>ApsisRS web service</title>
<style>
:root { color-scheme: dark; }
body { margin: 0; padding: 3rem 1.5rem; background: #0b0f17; color: #dfe7f1;
       font: 16px/1.6 ui-monospace, SFMono-Regular, Menlo, monospace; }
main { max-width: 46rem; margin: 0 auto; }
h1 { color: #7fd1ff; font-size: 1.5rem; }
code { background: #131a26; padding: .15rem .4rem; border-radius: .25rem; }
li { margin: .35rem 0; }
</style>
</head>
<body>
<main>
<h1>ApsisRS web service</h1>
<p>The service is running, but no frontend build is embedded in this binary.</p>
<p>Build the frontend first, then rebuild the Rust binary:</p>
<pre><code>cd frontend &amp;&amp; npm install &amp;&amp; npm run build
cargo build --release</code></pre>
<p>The JSON interfaces are available regardless:</p>
<ul>
<li><code>GET /health</code></li>
<li><code>GET /api/docs/index</code></li>
<li><code>GET /api/graph</code></li>
<li><code>GET /api/tools</code></li>
</ul>
</main>
</body>
</html>
"#;

/// Returns the embedded asset registered under `path`, if any.
///
/// The path is the request path with the leading slash removed, for example
/// `assets/index-abc123.js`. A directory request such as `/` is mapped to
/// `index.html` by the caller.
///
/// 返回登记在 `path` 之下的内嵌资源，若有。
///
/// 路径是去掉前导斜杠后的请求路径，例如 `assets/index-abc123.js`。诸如 `/`
/// 这样的目录请求由调用方映射到 `index.html`。
pub fn get(path: &str) -> Option<&'static [u8]> {
    ASSETS
        .iter()
        .find(|(name, _)| *name == path)
        .map(|(_, bytes)| *bytes)
}

/// Returns `true` when at least one asset is embedded.
///
/// 当至少有一个资源被嵌入时返回 `true`。
pub fn is_populated() -> bool {
    !ASSETS.is_empty()
}

/// Returns the placeholder page served when nothing is embedded.
///
/// 返回未嵌入任何内容时提供的占位页面。
pub fn placeholder() -> &'static [u8] {
    PLACEHOLDER.as_bytes()
}

/// Returns the media type for an asset path, based on its extension.
///
/// Text assets carry their charset so that a browser renders them without
/// guessing. An unknown extension is served as `application/octet-stream`,
/// which the browser will download rather than execute.
///
/// 依据扩展名返回某个资源路径的媒体类型。
///
/// 文本类资源带字符集，浏览器无须猜测即可渲染。未知扩展名按
/// `application/octet-stream` 提供，浏览器会下载它而不是执行它。
pub fn content_type(path: &str) -> &'static str {
    let extension = path.rsplit('.').next().unwrap_or_default();
    match extension {
        "html" | "htm" => "text/html; charset=utf-8",
        "js" | "mjs" => "text/javascript; charset=utf-8",
        "css" => "text/css; charset=utf-8",
        "json" => "application/json; charset=utf-8",
        "svg" => "image/svg+xml",
        "png" => "image/png",
        "jpg" | "jpeg" => "image/jpeg",
        "webp" => "image/webp",
        "gif" => "image/gif",
        "ico" => "image/vnd.microsoft.icon",
        "woff" => "font/woff",
        "woff2" => "font/woff2",
        "txt" => "text/plain; charset=utf-8",
        "map" => "application/json; charset=utf-8",
        "wasm" => "application/wasm",
        _ => "application/octet-stream",
    }
}
